</code></pre> <p>}</p> <p>delay(20); }</p> <p>// PROCESAR COMANDO void procesarComando(String cmd) {   cmd.trim();   cmd.toUpperCase();</p> <p>if (cmd.length() == 0) return;</p> <p>// Tomamos el primer carácter como comando principal   char c = cmd.charAt(0);</p> <p>Serial.print("\nComando recibido: ");   Serial.println(cmd);</p> <p>switch (c) {     case 'F':       motorAdelante();       break;</p> <pre><code>case 'B':
